function updateLastActivity(ss) {
  try {
    const urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) return;
    const lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      const keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        if (keys[i][0] === 'ULTIMA_ACTIVIDAD') {
          urlSheet.getRange(i + 2, 2).setValue(new Date().toLocaleString());
          return;
        }
      }
    }
    urlSheet.appendRow(['ULTIMA_ACTIVIDAD', new Date().toLocaleString(), 'Última acción']);
  } catch (e) {}
}

function setAppUrlInConfig(ss, appUrl) {
  try {
    const urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) return;
    const lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      const keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        if (keys[i][0] === 'WEB_APP_URL') {
          urlSheet.getRange(i + 2, 2).setValue(appUrl);
          return;
        }
      }
    }
    urlSheet.appendRow(['WEB_APP_URL', appUrl, 'URL de la app web']);
  } catch (e) {}
}

// =========================================================================
// LECTURA DE DATOS PARA SINCRONIZACIÓN EN VIVO (doGet)
// =========================================================================

function getTablesFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  const rows = sheet.getRange(2, 1, lastRow - 1, 8).getValues();
  return rows.map(function(r) {
    return {
      id: String(r[0]),
      name: String(r[1]),
      capacity: Number(r[2]) || 4,
      status: String(r[3]) || 'libre',
      occupiedByWaiterId: r[4] ? String(r[4]) : undefined,
      occupiedByWaiterName: r[5] ? String(r[5]) : undefined,
      currentOrderId: r[6] ? String(r[6]) : undefined,
      occupiedSince: r[7] ? String(r[7]) : undefined
    };
  });
}

function getMenuFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  const lastCol = Math.max(sheet.getLastColumn(), 9);
  const rows = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
  return rows.map(function(r) {
    var photoUrl = '';
    if (r[8] && String(r[8]).trim() !== '') {
      photoUrl = String(r[8]).trim();
    } else if (r[7] && String(r[7]).startsWith('http')) {
      photoUrl = String(r[7]).trim();
    }

    return {
      id: String(r[0]),
      name: String(r[1]),
      category: String(r[2]),
      price: Number(r[3]) || 0,
      description: String(r[4] || ''),
      available: String(r[5]).toUpperCase() !== 'NO',
      preparationTimeMinutes: Number(r[6]) || 10,
      image: photoUrl || undefined
    };
  });
}

function getUsersFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.USUARIOS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  // Read up to 6 columns: ID, NOMBRE, ROL, ACTIVO, USUARIO, PASSWORD
  const numCols = Math.min(sheet.getLastColumn(), 6);
  const rows = sheet.getRange(2, 1, lastRow - 1, numCols).getValues();
  return rows.map(function(r) {
    const name = String(r[1] || '');
    const defaultUsername = name.toLowerCase().replace(/s+/g, '');
    return {
      id: String(r[0]),
      name: name,
      role: String(r[2] || 'mesonero'),
      active: String(r[3] || 'SI').toUpperCase() !== 'NO',
      username: r[4] ? String(r[4]).trim() : defaultUsername,
      password: r[5] ? String(r[5]).trim() : '123'
    };
  });
}

function getOrdersFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  const activeOrders = {};
  const kitchenTickets = [];

  if (!sheet) return { activeOrders, kitchenTickets };
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return { activeOrders, kitchenTickets };

  const rows = sheet.getRange(2, 1, lastRow - 1, 10).getValues();

  for (var i = 0; i < rows.length; i++) {
    const r = rows[i];
    const orderId = String(r[0]);
    const status = String(r[5]);

    // Ignorar órdenes ya cobradas o canceladas
    if (status === 'cobrada' || status === 'cancelada') continue;

    var items = [];
    try {
      items = JSON.parse(r[7] || '[]');
    } catch(e) {
      items = [];
    }

    // NUNCA generar tickets ni órdenes activas sin platos
    if (!Array.isArray(items) || items.length === 0) continue;

    const orderObj = {
      id: orderId,
      orderNumber: String(r[1]),
      tableId: String(r[2]),
      tableName: String(r[3]),
      waiterName: String(r[4]),
      waiterId: '',
      status: status,
      currentRound: Number(r[6]) || 1,
      totalRounds: Number(r[6]) || 1,
      items: items,
      createdAt: String(r[8]),
      updatedAt: String(r[9])
    };

    activeOrders[orderId] = orderObj;

    // Crear tickets de cocina ÚNICAMENTE si hay platos y la comanda fue enviada a cocina
    if (items.length > 0 && (status === 'en_cocina' || status === 'preparando' || status === 'listo')) {
      var ticketStatus = 'en_cola';
      if (status === 'preparando') ticketStatus = 'preparando';
      if (status === 'listo') ticketStatus = 'listo';

      kitchenTickets.push({
        id: 'kt-' + orderId,
        orderId: orderId,
        orderNumber: orderObj.orderNumber,
        tableId: orderObj.tableId,
        tableName: orderObj.tableName,
        waiterName: orderObj.waiterName,
        roundNumber: orderObj.currentRound,
        isAdditional: orderObj.currentRound > 1,
        createdAt: orderObj.createdAt,
        status: ticketStatus,
        items: items
      });
    }
  }

  return { activeOrders, kitchenTickets };
}

function getPaymentsFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.VENTAS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  // Traer los últimos 50 cobros
  const startRow = Math.max(2, lastRow - 49);
  const numRows = lastRow - startRow + 1;
  const rows = sheet.getRange(startRow, 1, numRows, 11).getValues();

  return rows.reverse().map(function(r) {
    return {
      FECHA_PAGO: String(r[0]),
      NUMERO_PEDIDO: String(r[1]),
      MESA: String(r[2]),
      MESONERO: String(r[3]),
      SUBTOTAL: Number(r[4]) || 0,
      IMPUESTOS: Number(r[5]) || 0,
      PROPINA: Number(r[6]) || 0,
      TOTAL: Number(r[7]) || 0,
      METODO_PAGO: String(r[8]),
      REFERENCIA: String(r[9]),
      ITEMS_CONSUMIDOS: String(r[10]),
      syncedToSheet: true
    };
  });
}

// =========================================================================
// ESCRITURA DE DATOS EN TIEMPO REAL
// =========================================================================

function updateTableInSheet(ss, table) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();

  const rowValues = [
    table.id,
    table.name,
    table.capacity,
    table.status,
    table.occupiedByWaiterId || '',
    table.occupiedByWaiterName || '',
    table.currentOrderId || '',
    table.occupiedSince || new Date().toISOString()
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(table.id)) {
        sheet.getRange(i + 2, 1, 1, 8).setValues([rowValues]);
        return;
      }
    }
  }
  sheet.appendRow(rowValues);
}

function releaseTableInSheet(ss, tableId, orderId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (sheet) {
    const lastRow = sheet.getLastRow();
    if (lastRow > 1) {
      const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < ids.length; i++) {
        if (String(ids[i][0]) === String(tableId)) {
          sheet.getRange(i + 2, 4, 1, 5).setValues([['libre', '', '', '', '']]);
          break;
        }
      }
    }
  }

  // Limpiar o anular órdenes no cobradas asociadas a esta mesa en ORDENES
  const sheetOrdenes = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (sheetOrdenes) {
    const lastRowO = sheetOrdenes.getLastRow();
    if (lastRowO > 1) {
      for (var j = lastRowO; j >= 2; j--) {
        const rowId = String(sheetOrdenes.getRange(j, 1).getValue());
        const rowTableId = String(sheetOrdenes.getRange(j, 3).getValue());
        const rowStatus = String(sheetOrdenes.getRange(j, 6).getValue());
        const rawItems = sheetOrdenes.getRange(j, 8).getValue();

        var itemCount = 0;
        try {
          const parsed = JSON.parse(rawItems || '[]');
          itemCount = Array.isArray(parsed) ? parsed.length : 0;
        } catch(e) {
          itemCount = 0;
        }

        const matches = (orderId && rowId === String(orderId)) || (rowTableId === String(tableId));
        if (matches && rowStatus !== 'cobrada') {
          if (itemCount === 0 || rowStatus === 'abierta') {
            sheetOrdenes.deleteRow(j);
          } else {
            sheetOrdenes.getRange(j, 6).setValue('cancelada');
          }
        }
      }
    }
  }
}

function cancelOrderInSheet(ss, orderOrTicketId, tableId) {
  const sheetOrdenes = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheetOrdenes) return;
  const lastRow = sheetOrdenes.getLastRow();
  if (lastRow <= 1) return;

  const cleanId = String(orderOrTicketId).replace('kt-', '');
  for (var j = lastRow; j >= 2; j--) {
    const rowId = String(sheetOrdenes.getRange(j, 1).getValue());
    const rowTableId = String(sheetOrdenes.getRange(j, 3).getValue());
    const rawItems = sheetOrdenes.getRange(j, 8).getValue();

    var itemCount = 0;
    try {
      const parsed = JSON.parse(rawItems || '[]');
      itemCount = Array.isArray(parsed) ? parsed.length : 0;
    } catch(e) {
      itemCount = 0;
    }

    if (rowId === cleanId || (tableId && rowTableId === String(tableId))) {
      if (itemCount === 0) {
        sheetOrdenes.deleteRow(j);
      } else {
        sheetOrdenes.getRange(j, 6).setValue('cancelada');
      }
      return;
    }
  }
}

function removeEmptyOrdersFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  for (var i = lastRow; i >= 2; i--) {
    const rawItems = sheet.getRange(i, 8).getValue();
    const status = String(sheet.getRange(i, 6).getValue());
    var isEmpty = false;
    try {
      const parsed = JSON.parse(rawItems || '[]');
      if (!Array.isArray(parsed) || parsed.length === 0) {
        isEmpty = true;
      }
    } catch(e) {
      isEmpty = !rawItems || String(rawItems).trim() === '' || String(rawItems).trim() === '[]';
    }

    if (isEmpty && status !== 'cobrada') {
      sheet.deleteRow(i);
    }
  }
}

function saveOrderInSheet(ss, order) {
  // NUNCA guardar órdenes vacías sin platos en ORDENES
  if (!order || !Array.isArray(order.items) || order.items.length === 0) {
    return;
  }

  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  const itemsJson = JSON.stringify(order.items || []);

  const rowValues = [
    order.id,
    order.orderNumber,
    order.tableId,
    order.tableName,
    order.waiterName,
    order.status || 'en_cocina',
    order.currentRound || 1,
    itemsJson,
    order.createdAt || new Date().toISOString(),
    new Date().toISOString()
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(order.id)) {
        sheet.getRange(i + 2, 1, 1, 10).setValues([rowValues]);
        return;
      }
    }
  }
  sheet.appendRow(rowValues);
}

function updateOrderStatusInSheet(ss, orderOrTicketId, status, itemId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  // Extraer ID limpio
  const cleanId = String(orderOrTicketId).replace('kt-', '');
  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();

  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === cleanId) {
      const rowNum = i + 2;

      // Si la fila estaba vacía sin platos, eliminarla inmediatamente
      const currentJson = sheet.getRange(rowNum, 8).getValue();
      var items = [];
      try { items = JSON.parse(currentJson || '[]'); } catch(e) {}
      if (!Array.isArray(items) || items.length === 0) {
        sheet.deleteRow(rowNum);
        return;
      }

      if (status) {
        sheet.getRange(rowNum, 6).setValue(status);
      }
      if (itemId) {
        // Actualizar item específico dentro de JSON
        try {
          const updated = items.map(function(it) {
            return it.id === itemId ? Object.assign({}, it, { status: status }) : it;
          });
          sheet.getRange(rowNum, 8).setValue(JSON.stringify(updated));
        } catch(e) {}
      }
      sheet.getRange(rowNum, 10).setValue(new Date().toISOString());
      return;
    }
  }
}

function requestBillInSheet(ss, tableId, orderId) {
  const mSheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (mSheet) {
    const lastRow = mSheet.getLastRow();
    if (lastRow > 1) {
      const ids = mSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < ids.length; i++) {
        if (String(ids[i][0]) === String(tableId)) {
          mSheet.getRange(i + 2, 4).setValue('cuenta_solicitada');
          break;
        }
      }
    }
  }

  if (orderId) {
    const oSheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
    if (oSheet) {
      const lastRowO = oSheet.getLastRow();
      if (lastRowO > 1) {
        const idsO = oSheet.getRange(2, 1, lastRowO - 1, 1).getValues();
        for (var j = 0; j < idsO.length; j++) {
          if (String(idsO[j][0]) === String(orderId)) {
            oSheet.getRange(j + 2, 6).setValue('por_cobrar');
            break;
          }
        }
      }
    }
  }
}

function markOrderAsPaid(ss, orderNumber) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const orders = sheet.getRange(2, 2, lastRow - 1, 1).getValues();
  for (var i = 0; i < orders.length; i++) {
    if (String(orders[i][0]) === String(orderNumber)) {
      sheet.getRange(i + 2, 6).setValue('cobrada');
      sheet.getRange(i + 2, 10).setValue(new Date().toISOString());
      return;
    }
  }
}

function savePaymentInSheet(ss, p) {
  const sheet = ss.getSheetByName(SHEET_NAMES.VENTAS);
  if (!sheet) return;

  const row = [
    p.FECHA_PAGO || new Date().toLocaleString(),
    p.NUMERO_PEDIDO || '',
    p.MESA || '',
    p.MESONERO || '',
    Number(p.SUBTOTAL) || 0,
    Number(p.IMPUESTOS) || 0,
    Number(p.PROPINA) || 0,
    Number(p.TOTAL) || 0,
    p.METODO_PAGO || '',
    p.REFERENCIA || '',
    p.ITEMS_CONSUMIDOS || ''
  ];
  sheet.appendRow(row);
}

function saveMenuItemInSheet(ss, dish) {
  const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();

  // Asegurar que existan encabezados hasta la columna I (Columna 9)
  if (sheet.getLastColumn() < 9) {
    sheet.getRange(1, 8).setValue('PRECIO_BS');
    sheet.getRange(1, 9).setValue('FOTO_URL');
  }

  const precioBs = (Number(dish.price) || 0) * 54.50;
  const rowValues = [
    dish.id,
    dish.name,
    dish.category,
    Number(dish.price) || 0,
    dish.description || '',
    dish.available ? 'SI' : 'NO',
    Number(dish.preparationTimeMinutes) || 10,
    precioBs,
    dish.image || '' // Columna I: Enlace de foto en Google Drive
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(dish.id)) {
        sheet.getRange(i + 2, 1, 1, 9).setValues([rowValues]);
        return;
      }
    }
  }
  sheet.appendRow(rowValues);
}

/**
 * Sube una foto a Google Drive en la carpeta "ComandaPro_Platos",
 * le otorga permisos públicos de lectura y actualiza la Columna I en la tabla PLATOS.
 */
function uploadDishPhotoToDrive(ss, base64Data, mimeType, dishId, dishName) {
  if (!base64Data) {
    throw new Error('No se recibió el contenido de la imagen');
  }

  var rawBase64 = base64Data;
  var detectedMime = mimeType || 'image/jpeg';
  if (base64Data.indexOf(';base64,') !== -1) {
    var parts = base64Data.split(';base64,');
    detectedMime = parts[0].replace('data:', '') || detectedMime;
    rawBase64 = parts[1];
  }

  // Carpeta de Google Drive para los platos
  var folderName = 'ComandaPro_Platos';
  var folders = DriveApp.getFoldersByName(folderName);
  var folder;
  if (folders.hasNext()) {
    folder = folders.next();
  } else {
    folder = DriveApp.createFolder(folderName);
  }

  var ext = detectedMime.indexOf('png') !== -1 ? 'png' : (detectedMime.indexOf('webp') !== -1 ? 'webp' : 'jpg');
  var safeName = (dishName || 'plato').replace(/[^a-zA-Z0-9_-]/g, '_');
  var fileName = 'plato_' + (dishId || Date.now()) + '_' + safeName + '.' + ext;

  var decodedBytes = Utilities.base64Decode(rawBase64);
  var blob = Utilities.newBlob(decodedBytes, detectedMime, fileName);
  var file = folder.createFile(blob);

  // Permiso para que cualquiera con el enlace pueda visualizar la foto del plato
  try {
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
  } catch (e) {
    // Si la organización restringe compartir externamente, continuar
  }

  var fileId = file.getId();
  // Enlace directo compatible con previsualización en apps web
  var driveThumbnailUrl = 'https://drive.google.com/thumbnail?id=' + fileId + '&sz=w1000';
  var webViewUrl = 'https://drive.google.com/uc?export=view&id=' + fileId;

  // Registrar directamente en la Columna I de la tabla "PLATOS"
  if (dishId) {
    setDishPhotoInSheet(ss, dishId, driveThumbnailUrl);
  }

  return {
    fileId: fileId,
    driveUrl: driveThumbnailUrl,
    viewUrl: webViewUrl,
    folder: folderName,
    fileName: fileName
  };
}

function setDishPhotoInSheet(ss, dishId, photoUrl) {
  const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  if (sheet.getLastColumn() < 9) {
    sheet.getRange(1, 8).setValue('PRECIO_BS');
    sheet.getRange(1, 9).setValue('FOTO_URL');
  }

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(dishId)) {
      sheet.getRange(i + 2, 9).setValue(photoUrl); // Columna I (Columna 9)
      return;
    }
  }
}

function deleteMenuItemInSheet(ss, dishId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(dishId)) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}

function addTableToSheet(ss, table) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  sheet.appendRow([
    table.id,
    table.name,
    table.capacity,
    'libre',
    '',
    '',
    '',
    ''
  ]);
}

function updateTableDefinitionInSheet(ss, table) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    addTableToSheet(ss, table);
    return;
  }

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(table.id)) {
      sheet.getRange(i + 2, 2).setValue(table.name);
      sheet.getRange(i + 2, 3).setValue(table.capacity);
      if (table.status) sheet.getRange(i + 2, 4).setValue(table.status);
      return;
    }
  }
  // Si no se encontró, agregarlo
  addTableToSheet(ss, table);
}

function deleteTableFromSheet(ss, tableId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(tableId)) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}

function saveUserInSheet(ss, user) {
  const sheet = ss.getSheetByName(SHEET_NAMES.USUARIOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();

  const userRow = [
    user.id,
    user.name,
    user.role,
    user.active !== false ? 'SI' : 'NO',
    user.username || user.name.toLowerCase().replace(/\\s+/g, ''),
    user.password || '123'
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(user.id)) {
        sheet.getRange(i + 2, 1, 1, 6).setValues([userRow]);
        return;
      }
    }
  }

  sheet.appendRow(userRow);
}

function deleteUserFromSheet(ss, userId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.USUARIOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(userId)) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}
